def media_pesata(valori: list[float], pesi: list[float]) -> float:
    if len(valori) != len(pesi):
        raise ValueError("valori e pesi devono avere la stessa lunghezza")
    return sum(v * p for v, p in zip(valori, pesi)) / sum(pesi)

print(media_pesata([10, 20], [1, 3]))

